package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaMsDraft6 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_sharri_ma_amiltu" to DuaText("Berlindung dari Keburukan Amalan-Ku", "Ya Allah, aku berlindung kepada-Mu dari kejelekan apa yang aku kerjakan dan dari kejelekan apa yang belum aku kerjakan.", "Doa Nabi ﷺ, menurut Aisyah (RA).", "Perlindungan daripada akibat kedua-dua apa yang telah dilakukan dan apa yang tidak dilakukan."),
        "dua_jahdil_bala" to DuaText("Berlindung dari Ujian Berat", "Ya Allah, aku berlindung kepada-Mu dari cobaan yang berat, dari ditimpa kesengsaraan, dari takdir yang buruk dan dari riang musuh.", "Berlindung dari ujian yang berat dan riuh rendah musuh.", "Nabi ﷺ berlindung daripada empat perkara ini."),
        "dua_fitnat_ghina_faqr" to DuaText("Berlindung dari Ujian Kekayaan dan Kemiskinan", "Ya Allah, sesungguhnya aku berlindung kepada-Mu dari kemalasan dan usia tua, dari dosa dan hutang, dari fitnah dan azab kubur, dari fitnah dan azab neraka, dari kejahatan fitnah harta, dan dari fitnah kemiskinan.", "Berlindung dari fitnah kubur, neraka, harta dan kemiskinan (sebahagian daripada doa).", "Doa perlindungan yang menyeluruh dari Nabi ﷺ."),
        "dua_kufr_faqr" to DuaText("Berlindung daripada Kekufuran dan Kemiskinan", "Ya Allah, aku berlindung kepada-Mu dari kekufuran dan kemiskinan, dan aku berlindung kepada-Mu dari siksa kubur. Tiada Tuhan selain Engkau.", "Tiga kali pagi dan petang.", "Abu Bakrah (RA) mendengar Nabi ﷺ berkata demikian."),
        "dua_sharri_sami" to DuaText("Berlindung daripada Kejahatan PancainderaKu", "Ya Allah, aku berlindung kepada-Mu dari kejelekan pendengaranku, kejelekan pandanganku, kejelekan lidahku, kejelekan hatiku dan kejelekan hawa nafsuku.", "Diajarkan kepada Shakal ibn Humayd (RA).", "Doa untuk menjaga anggota badan dan diri daripada dosa."),
        "dua_hadm_gharaq" to DuaText("Perlindungan daripada Kematian Mengejut dan Kemalangan", "Ya Allah, aku berlindung kepada-Mu daripada dihempap ​​(bangunan), daripada jatuh dari ketinggian, daripada tenggelam, terbakar dan tua; dari syaitan yang menyesatkanku pada saat kematian, dari mati ketika lari dari jalan-Mu, dan dari mati karena sengatan (berbisa).", "Perlindungan daripada kemalangan dan kematian yang teruk.", "Doa perlindungan daripada Nabi ﷺ."),
        "dua_ju_khiyanah" to DuaText("Perlindungan daripada Kelaparan dan Pengkhianatan", "Ya Allah, aku berlindung kepada-Mu dari kelaparan, kerana ia adalah teman yang jahat, dan aku berlindung kepada-Mu dari pengkhianatan, kerana ia adalah orang yang jahat.", "Perlindungan daripada kelaparan dan pengkhianatan.", "Doa perlindungan daripada Nabi ﷺ."),
        "dua_huda_tuqa" to DuaText("Hidayah, Takwa, Kesucian dan Kecukupan", "Ya Allah, aku memohon kepada-Mu petunjuk, ketakwaan, kesucian dan kecukupan diri.", "Doa Nabi yang ringkas dan menyeluruh ﷺ.", "Empat rahmat asas agama dan dunia ini."),
        "dua_aslih_li_dini" to DuaText("Perbaikilah Agamaku, Dunia dan Akhirat", "Ya Allah, perbaikilah agamaku, yang menjadi pelindung segala urusanku; perbaikilah kehidupan duniaku, yang di dalamnya terdapat penghidupanku; dan perbaikilah akhiratku, yang kepadanya aku akan kembali. Jadikanlah hidup ini sebagai tambahan bagiku dalam setiap kebaikan, dan jadikanlah kematian sebagai pelepas bagiku dari setiap kejahatan.", "Memperbaharui agama, dunia dan Akhirat - ketiga-tiganya.", "Doa Nabi yang menyeluruh ﷺ."),
        "dua_musarrifal_qulub" to DuaText("Balikkanlah Hati Kami kepada KetaatanMu", "Ya Allah yang membolak-balikkan hati, palingkanlah hati kami kepada ketaatan kepada-Mu.", "Doa agar hati tetap teguh dalam ketaatan.", "Hati semua manusia berada di antara dua jari Tuhan Yang Maha Pemurah."),
        "dua_jannah_nar" to DuaText("Memohon Jannah, Berlindung dari Api", "Ya Allah, sesungguhnya aku memohon kepada-Mu syurga dan aku berlindung kepada-Mu dari api neraka.", "Selepas tasyahud atau pada bila-bila masa.", "Nabi ﷺ bersabda: Doa kami juga berkisar tentang ini."),
        "dua_khayri_kullih" to DuaText("Semua Baik, Kini dan Nanti", "Ya Allah, aku memohon kepada-Mu segala kebaikan - yang segera dan yang tertunda, yang aku ketahui dan yang tidak aku ketahui - dan aku berlindung kepada-Mu dari segala keburukan - yang segera dan yang tertunda, yang aku ketahui dan tidak aku ketahui. Ya Allah, sesungguhnya aku memohon kepada-Mu surga dan segala perkataan dan perbuatan yang mendekatkanku kepadanya, dan aku berlindung kepada-Mu dari neraka dan dari segala perkataan dan perbuatan yang mendekatkanku kepadanya.", "Nabi ﷺ mengajarkan doa komprehensif ini kepada Aisyah (RA) (sebahagian daripada doa).", "Doa yang mengumpulkan setiap kebaikan."),
        "dua_ihdini_saddidni" to DuaText("Bimbing Saya dan Pastikan Saya Tegak", "Ya Allah, bimbinglah aku dan tetapkanlah aku di jalan yang lurus.", "Nabi ﷺ mengajarkannya kepada Ali (RA).", "Anggaplah petunjuk sebagai petunjuk di sepanjang jalan, dan sadad sebagai lurusnya anak panah."),
        "dua_hubbaka" to DuaText("Meminta Cinta Allah", "Ya Allah, aku memohon kepada-Mu cinta-Mu, cinta orang-orang yang mencintai-Mu, dan amal yang membawaku kepada cinta-Mu. Ya Allah, jadikanlah cintaMu lebih aku cintai daripada diriku, keluargaku dan air yang sejuk.", "Doa Dawud (AS) yang diriwayatkan oleh Nabi ﷺ.", "Cinta kepada Allah adalah harta yang paling besar."),
        "dua_filal_khayrat" to DuaText("Berbuat Baik dan Meninggalkan Kejahatan", "Ya Allah, aku memohon kepada-Mu agar aku dapat mengerjakan amal yang soleh, meninggalkan kemungkaran dan mencintai orang-orang miskin, dan Engkau mengampuni dan merahmatiku. Dan apabila Engkau menghendaki cobaan terhadap suatu kaum, maka terimalah aku tanpa diuji. Aku memohon kepada-Mu cinta-Mu, cinta orang-orang yang mencintai-Mu, dan cinta amal yang mendekatkan aku kepada cinta-Mu.", "Allah mengajarkan doa ini kepada Nabi ﷺ dalam mimpi.", "Nabi ﷺ bersabda: itu benar, maka pelajarilah dan ajarkanlah."),
        "dua_bi_ilmikal_ghayb" to DuaText("Biarkan Saya Hidup Selagi Hidup Baik", "Ya Allah, dengan pengetahuan-Mu tentang yang ghaib dan kekuasaan-Mu atas ciptaan-Mu, hidupkanlah aku selama Engkau mengetahui kehidupan itu lebih baik untukku, dan ambillah aku ketika Engkau mengetahui kematian itu lebih baik untukku. Ya Allah, sesungguhnya aku memohon kepada-Mu rasa takut kepada-Mu secara tertutup dan di hadapan umum, perkataan yang benar dalam keredaan dan kemarahan, dan kesederhanaan dalam kemiskinan dan kekayaan.", "Doa doa Ammar ibn Yasir (RA) (bahagian pembukaan).", "Nabi ﷺ membuat doa ini dalam doa."),
        "dua_ism_azam_mannan" to DuaText("Ism-e-Azam: Al-Mannan", "Ya Allah, aku memohon kepada-Mu, bagi-Mu segala pujian; tiada Tuhan selain Engkau, Yang Maha Pemberi nikmat, Pencipta langit dan bumi. Wahai Pemilik Keagungan dan Kemuliaan, Wahai Yang Hidup Kekal, Wahai Pemelihara!", "Nabi ﷺ berkata lelaki ini berdoa dengan Nama Allah yang Maha Agung.", "Doa yang dibuat dengan Nama ini dijawab."),
        "dua_ism_azam_ahad_samad" to DuaText("Ism-e-Azam: Al-Ahad As-Samad", "Ya Allah, aku memohon kepadaMu, kerana aku bersaksi bahawa Engkau adalah Allah; tidak ada Tuhan selain Engkau, Yang Maha Esa, Yang Maha Kaya, yang tidak beranak dan tidak pula diperanakkan, dan tidak ada yang setara dengan Dia.", "Nabi ﷺ berkata lelaki ini bertanya kepada Allah dengan Nama-Nya yang Maha Agung.", "Apabila diminta olehnya, Dia memberi; apabila dipanggil olehnya, Dia menjawab."),
        "dua_thabbitni_hadiyan" to DuaText("Jadikan Saya Teguh, Dibimbing dan Pembimbing", "Ya Allah, teguhkanlah aku, dan jadikanlah aku orang yang memberi petunjuk dan mendapat petunjuk.", "Nabi ﷺ membuat doa ini untuk Jarir (RA) (untuk diri sendiri sebut 'thabbitni').", "Doa asal untuk Jarir (RA) menggunakan perkataan 'thabbit-hu'."),
        "dua_rabbighfir_tub_alayya" to DuaText("Ampunilah Aku dan Terimalah Taubatku", "Ya Tuhanku, ampunilah aku dan terimalah taubatku. Sesungguhnya Engkau Maha Penerima taubat lagi Maha Penyayang.", "Seratus kali dalam sekali duduk - amalan Nabi ﷺ.", "Para Sahabat menghitung Nabi ﷺ mengucapkannya seratus kali dalam sekali duduk."),
        "dua_rafiq_ala" to DuaText("Doa Orang Yang Sekarat", "Ya Allah, ampunilah aku, rahmatilah aku dan gabungkanlah aku dengan Sahabat yang Maha Tinggi.", "Doa terakhir Nabi ﷺ — untuk orang sakit untuk mengatakan untuk dirinya sendiri.", "Nabi ﷺ melakukan doa ini pada saat beliau wafat."),
        "dua_la_bas_tahur" to DuaText("Menghibur Orang Sakit: Penyucian", "Tiada bahaya; itu adalah penyucian (dari dosa), jika Allah menghendaki.", "Untuk menghiburkan orang sakit ketika melawat.", "Nabi ﷺ bersabda demikian ketika menziarahi orang sakit."),
        "dua_talqeen" to DuaText("Talqeen for the Dying", "Tiada yang berhak disembah melainkan Allah.", "Lafaz kalimah dekat orang yang nazak (jangan paksa dia sebut).", "Sesiapa yang akhir perkataan 'La ilaha illallah' akan masuk syurga (Abu Dawud 3116)."),
        "dua_ahyini_ma_kanat" to DuaText("Daripada Mengharapkan Kematian", "Ya Allah, hidupkanlah aku selagi hidup itu lebih baik bagiku, dan ambillah aku ketika kematian itu lebih baik bagiku.", "Bukannya mengharapkan kematian dalam kesusahan.", "Nabi ﷺ melarang mengharapkan kematian dan mengajarkannya."),
        "dua_for_one_i_cursed" to DuaText("Untuk Seseorang yang Saya Sakiti dengan Kata-kata", "Ya Allah, setiap orang mukmin yang aku hina, jadikanlah hal itu sebagai sarana mendekatkan diri kepada-Mu pada hari kiamat.", "Untuk seseorang yang anda bercakap buruk dengan marah.", "Doa Nabi ﷺ."),
        "dua_praising_someone" to DuaText("Apabila Memuji Seseorang", "Saya menganggap fulan seperti ini, dan Allah adalah Penghitungnya, dan saya tidak menjamin kesucian seseorang di hadapan Allah.", "Apabila memuji seseorang, bukannya berlebih-lebihan.", "Nabi ﷺ mengajar adab pujian ini."),
        "dua_being_praised" to DuaText("Apabila Anda Dipuji", "Ya Allah, janganlah Engkau hisab aku atas apa yang mereka katakan, dan ampunilah aku atas apa yang mereka tidak ketahui.", "Apabila mendengar diri sendiri dipuji — amalan Sahabat (RA).", "Cara untuk mengelakkan sifat sombong apabila dipuji."),
        "dua_non_muslim_sneezes" to DuaText("Apabila Orang Bukan Islam Bersin", "Semoga Allah memberi petunjuk dan memperbaiki urusanmu.", "Apabila orang bukan Islam bersin dan mengucapkan 'Alhamdulillah'.", "Orang Yahudi akan bersin dekat Nabi ﷺ dengan harapan baginda akan mengucapkan 'Yarhamukallah', dan baginda akan berkata ini."),
        "dua_reply_ahl_kitab_salam" to DuaText("Membalas Salam Ahli Kitab", "Dan atas kamu.", "Apabila Ahli Kitab memberi salam.", "Arahan Nabi ﷺ."),
        "dua_fasting_invited" to DuaText("Apabila Dijemput Ketika Berpuasa", "saya sedang berpuasa.", "Apabila dijemput semasa berpuasa, atau apabila seseorang bergaduh dengan anda.", "Jika orang yang berpuasa menerima jemputan, hendaklah dia berdoa untuk tuan rumah."),
        "dua_for_who_gave_drink" to DuaText("Untuk Sesiapa yang Memberi Aku", "Ya Allah, berilah makan orang yang memberiku makan dan berilah minum orang yang memberiku minum.", "Bagi sesiapa yang memberi kamu makan atau minum.", "Nabi ﷺ membuat doa ini untuk al-Miqdad (RA)."),
        "dua_eid_greeting" to DuaText("Salam Aidilfitri", "Semoga Allah menerima (amal soleh) dari kami dan dari kamu.", "Satu sama lain pada hari raya - amalan para sahabat yang mulia (RA).", "Para sahabat berkata demikian ketika bertemu pada hari raya."),
        "dua_wedding_night" to DuaText("Untuk Pengantin Selepas Nikah", "Ya Allah, sesungguhnya aku memohon kepada-Mu kebaikannya dan kebaikan alam yang Engkau ciptakan dengannya, dan aku berlindung kepada-Mu dari kejahatannya dan kejahatan alam yang Engkau ciptakan dengannya.", "Selepas akad nikah, meletakkan tangan di dahi isteri.", "Ajaran Nabi ﷺ — berkat dalam perkahwinan."),
        "dua_istisqa_ibadak" to DuaText("Sirami Hamba dan Haiwan Anda", "Ya Allah, berikanlah air kepada hamba-hamba-Mu dan binatang-binatang-Mu, sebarkanlah rahmat-Mu dan hidupkanlah tanah-Mu yang mati.", "Meminta hujan (istisqa).", "Nabi ﷺ membuat doa ini untuk hujan."),
        "dua_seeing_clouds" to DuaText("Melihat Awan Gelap", "Ya Allah, aku berlindung kepada-Mu dari kejahatannya.", "Apabila melihat awan gelap di langit; jika hujan, sebutlah 'Allahumma sayyiban nafi'a'.", "Apabila melihat awan, Nabi ﷺ akan meninggalkan apa yang dia lakukan dan berdoa ini."),
        "dua_jamarat" to DuaText("Merejam Jamarat", "Allah Maha Besar.", "Dengan setiap kerikil yang dilemparkan.", "Nabi ﷺ bertakbir dengan setiap kerikil, kemudian selepas jamrah pertama dan kedua menghadap kiblat dan berdoa yang panjang."),
        "dua_rabbi_ainni" to DuaText("Tuhanku, Tolonglah Aku dan Jangan Melawan Aku", "Ya Tuhanku, tolonglah aku dan jangan tolong orang lain terhadapku, berikanlah kemenangan kepadaku dan janganlah Engkau berikan kemenangan kepada orang lain atasku, rencanakanlah untukku dan janganlah Engkau merancang untuk menentangku, bimbinglah aku dan mudahkanlah bagiku petunjuk, dan tolonglah aku terhadap orang yang menzalimiku.", "Doa Nabi yang menyeluruh ﷺ (bahagian pembukaan).", "Doa yang mengumpulkan setiap pertolongan dalam agama dan dunia ini."),
        "dua_ati_nafsi_taqwaha" to DuaText("Kurniakan Jiwaku Taqwa", "Ya Allah, anugerahkan kepada jiwaku ketakwaannya dan sucikanlah ia, kerana Engkaulah sebaik-baik yang mensucikannya. Anda adalah Penjaganya dan Tuannya.", "Untuk memperbaharui dan menyucikan diri.", "Nabi ﷺ pernah membuat doa ini."),
        "dua_iqsim_lana_khashyatik" to DuaText("Berikan Kami Ketakutan Sebegitu Kepada Anda", "Ya Allah, kurniakanlah kepada kami rasa takut kepada-Mu untuk menyekat antara kami dan kemaksiatan kepada-Mu, ketaatan yang cukup untuk membawa kami ke syurga-Mu, dan kepastian yang cukup untuk memudahkan kami menghadapi musibah dunia. Biarkan kami menikmati pendengaran kami, penglihatan kami dan kekuatan kami selagi Engkau menghidupkan kami, dan menjadikan mereka bertahan lebih lama daripada kami. Balas dendam kami kepada orang yang menzalimi kami, tolonglah kami terhadap musuh kami, jangan biarkan musibah kami dalam agama kami, jangan jadikan dunia ini sebagai kebimbangan terbesar kami atau batas pengetahuan kami, dan jangan jadikan atas kami orang-orang yang tidak akan mengasihani kami.", "Apabila bangkit dari perhimpunan — Nabi ﷺ jarang bangkit tanpa berdoa ini.", "Doa yang menyeluruh untuk kebaikan agama, dunia dan Akhirat."),
        "dua_infani_bima_allamtani" to DuaText("Manfaatkan Saya Dengan Apa yang Anda Ajar Saya", "Ya Allah, berikanlah manfaat kepadaku dengan apa yang telah Engkau ajarkan kepadaku, ajarkanlah kepadaku apa yang bermanfaat bagiku, dan tambahkanlah ilmu kepadaku.", "Semasa menuntut ilmu atau sebelum belajar.", "Doa untuk ilmu yang bermanfaat dan mengamalkannya."),
    )
}
